import{_ as s,o,c as e,af as d}from"./chunks/framework.B28LkSoM.js";const p=JSON.parse('{"title":"RESTful接口规范","description":"REST 架构风格：用 URL 定位资源、用 HTTP 动词描述操作，以及传统风格与 REST 风格接口的对比","frontmatter":{"title":"RESTful接口规范","published":"2026-09-20T00:00:00.000Z","description":"REST 架构风格：用 URL 定位资源、用 HTTP 动词描述操作，以及传统风格与 REST 风格接口的对比","tags":["Python","Web开发"],"image":"https://img.tsh520.cn/file/blog/post-covers/python-65-restful.webp","order":65,"date":"2026-09-20T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Python学习笔记/65-RESTful接口规范.md","filePath":"posts/学习文档/Python学习笔记/65-RESTful接口规范.md"}'),r={name:"posts/学习文档/Python学习笔记/65-RESTful接口规范.md"};function a(n,t,i,l,c,u){return o(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789862400000"},[...t[0]||(t[0]=[d(`<h2 id="restful-是什么" tabindex="-1">RESTful 是什么 <a class="header-anchor" href="#restful-是什么" aria-label="Permalink to &quot;RESTful 是什么&quot;">​</a></h2><p>Restful 指的是<strong>遵循 REST 架构风格的 API 接口服务</strong>，而 REST（REpresentational State Transfer，表述性状态转换）是一种软件架构风格。</p><p>它解决的是&quot;接口怎么起名字&quot;的问题：</p><table tabindex="0"><thead><tr><th>传统风格 url</th><th>请求方式</th><th>含义</th><th>备注</th></tr></thead><tbody><tr><td><code>/user/getById?id=1</code></td><td>GET</td><td>查询 id 为 1 的用户</td><td>不规范、难维护</td></tr><tr><td><code>/user/saveUser</code></td><td>POST</td><td>新增用户</td><td></td></tr><tr><td><code>/user/updateUser</code></td><td>POST</td><td>修改用户</td><td></td></tr><tr><td><code>/user/deleteUser?id=1</code></td><td>GET</td><td>删除 id 为 1 的用户</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>REST 风格 url</th><th>请求方式</th><th>含义</th></tr></thead><tbody><tr><td><code>/users/1</code></td><td>GET</td><td>查询 id 为 1 的用户</td></tr><tr><td><code>/users</code></td><td>POST</td><td>新增用户</td></tr><tr><td><code>/users</code></td><td>PUT</td><td>修改用户</td></tr><tr><td><code>/users/1</code></td><td>DELETE</td><td>删除 id 为 1 的用户</td></tr></tbody></table><h2 id="两条核心特点" tabindex="-1">两条核心特点 <a class="header-anchor" href="#两条核心特点" aria-label="Permalink to &quot;两条核心特点&quot;">​</a></h2><ol><li><strong>URL 定位资源</strong>：地址里只写&quot;操作哪个资源&quot;，不写动作（所以不出现 <code>getById</code>、<code>saveUser</code> 这类动词）</li><li><strong>HTTP 动词描述操作</strong>：具体做什么由请求方式决定</li></ol><table tabindex="0"><thead><tr><th>请求方式</th><th>操作</th></tr></thead><tbody><tr><td>GET</td><td>查询</td></tr><tr><td>POST</td><td>新增</td></tr><tr><td>PUT</td><td>修改</td></tr><tr><td>DELETE</td><td>删除</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>两个容易踩的点： ① <strong>REST 是风格、是约定，不是规定</strong>——约定可以打破。 ② 描述&quot;功能模块&quot;通常用<strong>复数形式</strong>（加 s）表示这一类资源而非单个资源：<code>users</code>、<code>books</code>、<code>items</code>。</p></div><h2 id="本项目用到的接口-对照理解" tabindex="-1">本项目用到的接口（对照理解） <a class="header-anchor" href="#本项目用到的接口-对照理解" aria-label="Permalink to &quot;本项目用到的接口（对照理解）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>方式</th><th>含义</th></tr></thead><tbody><tr><td><code>/api/sessions</code></td><td>POST</td><td>新建会话</td></tr><tr><td><code>/api/sessions</code></td><td>GET</td><td>获取会话列表</td></tr><tr><td><code>/api/sessions/{id}</code></td><td>GET</td><td>查询指定会话</td></tr><tr><td><code>/api/sessions/{id}</code></td><td>DELETE</td><td>删除指定会话</td></tr><tr><td><code>/api/chat</code></td><td>POST</td><td>与 AI 交互（提交一条消息）</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/python学习笔记/66-汉字谜盒-环境搭建与静态资源/">汉字谜盒-环境搭建与静态资源</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>REST 全称 <strong>REpresentational State Transfer</strong>，中文<strong>表述性状态转换</strong>，它是一种软件<strong>架构风格</strong>；遵循 REST 架构风格的接口服务叫作 <strong>RESTful</strong></li><li>REST 的两条核心特点：用 <strong>URL</strong> 定位资源、用 <strong>HTTP 动词</strong>描述操作；所以地址里只有&quot;要操作哪个<strong>资源</strong>&quot;，&quot;要做什么&quot;由<strong>请求方式</strong>决定</li><li>四种请求方式对应的操作：GET <strong>查询</strong>、POST <strong>新增</strong>、PUT <strong>修改</strong>、DELETE <strong>删除</strong></li><li>传统 → REST 对照（填&quot;请求方式 + 路径&quot;）：<code>/user/getById?id=1</code>（传统用 GET）→ <strong>GET</strong> + <code>/users/1</code>；<code>/user/saveUser</code>（传统用 POST）→ <strong>POST</strong> + <code>/users</code>；<code>/user/updateUser</code>（传统用 POST）→ <strong>PUT</strong> + <code>/users</code>；<code>/user/deleteUser?id=1</code>（传统用 GET）→ <strong>DELETE</strong> + <code>/users/1</code></li><li>看 REST 接口说含义：<code>/users</code> + POST 表示<strong>新增用户</strong>；<code>/users/1</code> + GET 表示<strong>查询 id 为 1 的用户</strong>；<code>/users</code> + PUT 表示<strong>修改用户</strong>；<code>/users/1</code> + DELETE 表示<strong>删除 id 为 1 的用户</strong></li><li>描述&quot;功能模块&quot;通常用<strong>复数</strong>形式（如 <code>users</code>、<code>books</code>，表示&quot;这一类&quot;而不是单个）；REST 是<strong>风格</strong>、是<strong>约定</strong>，不是<strong>规定</strong>，所以约定<strong>可以</strong>打破</li><li>传统风格的毛病：动作被写进了 <strong>URL（地址）</strong>（如 <code>getById</code>、<code>saveUser</code>），同一个资源的一套增删改查要拼出 <strong>4</strong> 个不同的地址，所以说它&quot;不规范、难<strong>维护</strong>&quot;；REST 风格里同一个资源只用 <strong>1</strong> 个地址</li><li>本项目的接口（一）：新建会话用 <strong>POST</strong> 请求 <code>/api/sessions</code>；获取会话列表用 <strong>GET</strong> 请求 <code>/api/sessions</code>；与 AI 交互（提交一条消息）用 <strong>POST</strong> 请求 <code>/api/chat</code></li><li>本项目的接口（二）：查询指定会话用 <strong>GET</strong> 请求 <code>/api/sessions/{id}</code>；删除指定会话用 <strong>DELETE</strong> 请求 <code>/api/sessions/{id}</code>；地址里的 <code>{id}</code> 表示<strong>路径里的变量（占位符）</strong></li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1</strong> 把 <code>/book/getBookById?id=5</code>、<code>/book/addBook</code>、<code>/book/delete?id=5</code> 三个传统接口改写成 REST 风格</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：URL 里只留&quot;复数名词表示的资源&quot;（图书 → books），把动作词（getBookById、addBook、delete）丢掉，再想每个操作该交给哪个 HTTP 动词、资源后面要不要带编号</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /books/5      查询 id 为 5 的图书</span></span>
<span class="line"><span>POST   /books        新增图书</span></span>
<span class="line"><span>DELETE /books/5      删除 id 为 5 的图书</span></span></code></pre></div></details></li><li><p>[ ] <strong>2-2</strong> 一个&quot;学生管理&quot;系统要支持：查列表、查单个、新增、修改、删除，写出 5 个 REST 接口（路径 + 方式）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先定唯一的资源名（学生 → students），再按&quot;列表 / 单个 / 新增 / 修改 / 删除&quot;五种操作各挑一个动词与路径</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /students        查询列表</span></span>
<span class="line"><span>GET    /students/{id}   查询单个</span></span>
<span class="line"><span>POST   /students        新增</span></span>
<span class="line"><span>PUT    /students/{id}   修改</span></span>
<span class="line"><span>DELETE /students/{id}   删除</span></span></code></pre></div></details></li><li><p>[ ] <strong>2-3</strong> 为什么 DELETE 用 <code>/users/1</code> 而不是 <code>/users/delete/1</code>？（用&quot;URL 定位资源&quot;这句话解释）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：从&quot;URL 只负责定位资源&quot;出发——<code>/users/1</code> 已经把&quot;操作哪个用户&quot;说清楚了，&quot;要做什么&quot;交给请求方式</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 因为 URL 只负责<strong>定位资源</strong>（&quot;要操作 id 为 1 的那个用户&quot;），&quot;要做什么&quot;由 HTTP 动词（DELETE）表达。把动作塞进 URL 里（<code>/users/delete/1</code>）就退化成了传统风格，又多又乱。</p></details></li></ul>`,18)])])}const h=s(r,[["render",a]]);export{p as __pageData,h as default};
